//! Gate V2-Golden test suite for `WP-2.2a` (`GameMath` fdlibm, 2,000 reference vectors
//! generated by linking `tests/cpp_harness/gen_gamemath_vectors.c` against the exact
//! `libgm.a` shipped in the `GeneralsXZH` reference build).
//!
//! Every output is compared bit-for-bit. When the reference result is a NaN, only NaN-ness
//! is asserted, because the sign/payload of a freshly generated default NaN (`x - x` on Inf)
//! is ISA-defined (x86 `0xffc00000` vs ARM `0x7fc00000`) for the C reference too.

use zh_common::golden_json::{extract_vector_lines, get_i32, get_u32, get_u64};
use zh_common::math::{
    gm_acosf, gm_asinf, gm_atan2f, gm_atanf, gm_ceilf, gm_copysignf, gm_cosf, gm_fabsf, gm_floorf,
    gm_rintf, gm_roundf, gm_scalbnf, gm_sinf, gm_sqrt, gm_sqrtf, gm_tanf, normalize_angle,
};

const GAMEMATH_JSON: &str = include_str!("../../../docs/golden_vectors/WP2_2a_GameMath.json");

fn check_f32(seed: u32, name: &str, got: f32, want_bits: u32, failures: &mut Vec<String>) {
    let want = f32::from_bits(want_bits);
    let ok = if want.is_nan() { got.is_nan() } else { got.to_bits() == want_bits };
    if !ok {
        failures.push(format!(
            "seed {seed} {name}: got 0x{:08x} ({got:e}) want 0x{want_bits:08x} ({want:e})",
            got.to_bits()
        ));
    }
}

#[test]
fn test_wp2_2a_gamemath_2000_golden_vectors() {
    let lines = extract_vector_lines(GAMEMATH_JSON);
    assert_eq!(lines.len(), 2000, "Expected 2,000 golden vectors in WP2_2a_GameMath.json");

    let mut failures = Vec::new();
    for line in lines {
        let seed = get_u32(line, "seed").expect("seed");
        let x = f32::from_bits(get_u32(line, "x").expect("x"));
        let y = f32::from_bits(get_u32(line, "y").expect("y"));
        let u = f32::from_bits(get_u32(line, "u").expect("u"));
        let n = get_i32(line, "n").expect("n");
        let xd = f64::from_bits(get_u64(line, "xd").expect("xd"));
        let ax = gm_fabsf(x);

        let f = |k: &str| get_u32(line, k).unwrap_or_else(|| panic!("seed {seed} missing {k}"));
        check_f32(seed, "sin", gm_sinf(x), f("sin"), &mut failures);
        check_f32(seed, "cos", gm_cosf(x), f("cos"), &mut failures);
        check_f32(seed, "tan", gm_tanf(x), f("tan"), &mut failures);
        check_f32(seed, "asin", gm_asinf(u), f("asin"), &mut failures);
        check_f32(seed, "acos", gm_acosf(u), f("acos"), &mut failures);
        check_f32(seed, "atan", gm_atanf(x), f("atan"), &mut failures);
        check_f32(seed, "atan2", gm_atan2f(y, x), f("atan2"), &mut failures);
        check_f32(seed, "sqrt", gm_sqrtf(ax), f("sqrt"), &mut failures);
        check_f32(seed, "floor", gm_floorf(x), f("floor"), &mut failures);
        check_f32(seed, "ceil", gm_ceilf(x), f("ceil"), &mut failures);
        check_f32(seed, "fabs", ax, f("fabs"), &mut failures);
        check_f32(seed, "rint", gm_rintf(x), f("rint"), &mut failures);
        check_f32(seed, "round", gm_roundf(x), f("round"), &mut failures);
        check_f32(seed, "scalbn", gm_scalbnf(x, n), f("scalbn"), &mut failures);
        check_f32(seed, "copysign", gm_copysignf(x, y), f("copysign"), &mut failures);
        check_f32(seed, "norm_angle", normalize_angle(x), f("norm_angle"), &mut failures);

        let want_d = get_u64(line, "sqrtd").expect("sqrtd");
        let got_d = gm_sqrt(if xd < 0.0 { -xd } else { xd });
        let ok_d = if f64::from_bits(want_d).is_nan() { got_d.is_nan() } else { got_d.to_bits() == want_d };
        if !ok_d {
            failures.push(format!("seed {seed} sqrtd: got 0x{:016x} want 0x{want_d:016x}", got_d.to_bits()));
        }
    }

    if !failures.is_empty() {
        let shown: Vec<_> = failures.iter().take(40).cloned().collect();
        panic!("{} WP-2.2a GameMath mismatches (first {}):\n{}", failures.len(), shown.len(), shown.join("\n"));
    }
}
